#pragma pack(push,1)
struct ResultHeader { char magic[8]; uint32_t version,genomes,cases; };
struct ResultBin { int32_t own_money,opp_money; uint16_t action_changes,activations,flags,reserved; uint64_t action_trace_hash; };
#pragma pack(pop)
static_assert(sizeof(ResultBin)==24,"B4IC1 result ABI drift");

struct CaseHost { std::string path; int seat=0; uint64_t seed=0; int family=0,protected_flag=0,own_history=0,role=0; };
struct CaseDev { int tape=0,seat=0; uint64_t seed=0; int family=0,protected_flag=0,own_history=0,role=0; };
struct OppDesc { int first=0,count=0; };

struct DevicePolicyOwner4 {
    bonsaikg4::Node4*n=nullptr;uint16_t*c=nullptr;bonsaikg4::BbDecl4*bb=nullptr;bonsaikg4::ValueRef4*v=nullptr;
    bonsaikg4::FeatureArgRef4*a=nullptr;bonsaikg4::Predicate4*q=nullptr;bonsaikg4::Lifecycle4*l=nullptr;bonsaikg4::Effect4*e=nullptr;
    ~DevicePolicyOwner4(){if(n)cudaFree(n);if(c)cudaFree(c);if(bb)cudaFree(bb);if(v)cudaFree(v);if(a)cudaFree(a);if(q)cudaFree(q);if(l)cudaFree(l);if(e)cudaFree(e);}
};
template<class T> static T* cp(const std::vector<T>&v){if(v.empty())return nullptr;T*d=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&d,v.size()*sizeof(T)));KAGCUDA_CHECK(cudaMemcpy(d,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));return d;}
static std::vector<std::string> split_tab(const std::string&s){std::vector<std::string>o;size_t p=0;for(;;){size_t q=s.find('\t',p);o.push_back(s.substr(p,q==std::string::npos?std::string::npos:q-p));if(q==std::string::npos)break;p=q+1;}return o;}
static std::vector<CaseHost> load_cases(const std::string&p){std::ifstream in(p);if(!in)throw std::runtime_error("cannot open cases: "+p);std::vector<CaseHost>o;std::string line;while(std::getline(in,line)){if(line.empty()||line[0]=='#')continue;auto z=split_tab(line);if(z.size()!=7)throw std::runtime_error("invariant case needs 7 tab fields");CaseHost c;c.path=z[0];c.seat=std::stoi(z[1]);c.seed=std::stoull(z[2]);c.family=std::stoi(z[3]);c.protected_flag=std::stoi(z[4]);c.own_history=std::stoi(z[5]);c.role=std::stoi(z[6]);if(c.seat<0||c.seat>1)throw std::runtime_error("invalid case seat");o.push_back(c);}if(o.empty())throw std::runtime_error("empty cases");return o;}
static std::vector<inv::Candidate> load_candidates(const std::string&p){std::ifstream in(p,std::ios::binary);if(!in)throw std::runtime_error("cannot open B4IM1 candidates");inv::FileHeader h{};in.read((char*)&h,sizeof(h));const char magic[8]={'B','4','I','M','1','\0','\0','\0'};if(!in||std::memcmp(h.magic,magic,8)||h.version!=1||h.count<1||h.count>100000)throw std::runtime_error("invalid B4IM1 header");std::vector<inv::Candidate>o(h.count);in.read((char*)o.data(),o.size()*sizeof(o[0]));char extra=0;if(!in||in.read(&extra,1))throw std::runtime_error("invalid/trailing B4IM1 payload");for(const auto&c:o)if(!inv::valid_candidate(c))throw std::runtime_error("invalid B4IM1 candidate");return o;}

static bonsaikg_v6::RoutePack load_legacy_pack(const std::string&path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("cannot open legacy route pack");std::vector<uint8_t>raw((std::istreambuf_iterator<char>(in)),{});auto full=bonsaikg::sha256_bytes(raw);if(bonsaikg_v6::hash_hex(full)!=bonsaikg4_champion::LEGACY_ROUTE_PACK_SHA256)throw std::runtime_error("legacy route pack SHA mismatch");bonsaikg_v6::PackHeader h{};if(raw.size()<sizeof(h))throw std::runtime_error("short legacy route pack");std::memcpy(&h,raw.data(),sizeof(h));size_t db=(size_t)h.route_count*sizeof(bonsaikg_v6::RouteDesc);size_t expected=sizeof(h)+db+(size_t)h.action_count*sizeof(bonsaikg_v6::PackedAction);if(raw.size()!=expected)throw std::runtime_error("legacy route pack size mismatch");bonsaikg_v6::RoutePack o;o.routes.resize(h.route_count);o.actions.resize(h.action_count);std::memcpy(o.routes.data(),raw.data()+sizeof(h),db);std::memcpy(o.actions.data(),raw.data()+sizeof(h)+db,o.actions.size()*sizeof(o.actions[0]));return o;}

struct DeviceBasePack {const bonsaikg_v6::RouteDesc*routes=nullptr;const bonsaikg_v6::PackedAction*actions=nullptr;int n=0;__device__ __forceinline__ const bonsaikg_v6::PackedAction*at(uint16_t route,int step)const{for(int i=0;i<n;++i)if(routes[i].route_id==route){int s=step;if(s<0)s=0;if(s>=routes[i].steps)s=routes[i].steps-1;return actions+routes[i].first+s;}return nullptr;}};

__device__ __forceinline__ bool same_action(const Action&a,const Action&b){if(a.n_units!=b.n_units||a.n_orders!=b.n_orders)return false;for(int i=0;i<a.n_units;++i)if(a.units[i].op!=b.units[i].op||a.units[i].arg!=b.units[i].arg||a.units[i].n!=b.units[i].n)return false;for(int i=0;i<a.n_orders;++i)if(a.orders[i].op!=b.orders[i].op||a.orders[i].item!=b.orders[i].item||a.orders[i].n!=b.orders[i].n)return false;return true;}
__device__ __forceinline__ uint64_t mix(uint64_t h,uint64_t x){h^=x;h*=1099511628211ull;return h;}
__device__ __forceinline__ uint64_t trace_hash(uint64_t h,int step,const Action&a){h=mix(h,(uint64_t)(uint32_t)step);h=mix(h,(uint64_t)(uint32_t)a.n_units);for(int i=0;i<a.n_units;++i){const auto&u=a.units[i];h=mix(h,(uint64_t)u.op|((uint64_t)u.arg<<8)|((uint64_t)(uint16_t)u.n<<16)|((uint64_t)(uint32_t)i<<32));}h=mix(h,(uint64_t)(uint32_t)a.n_orders);for(int i=0;i<a.n_orders;++i){const auto&o=a.orders[i];h=mix(h,(uint64_t)o.op|((uint64_t)o.item<<8)|((uint64_t)(uint32_t)o.n<<16)|((uint64_t)(uint32_t)i<<48));}return h;}
__device__ __forceinline__ void reconcile_feed(const int32_t*bb,int first,int count,Action&a){for(int u=0;u<count&&u<a.n_units;++u)if(bb[first+u]&&a.units[u].op==OP_FEED)a.units[u]=UnitAction{};}

__device__ __forceinline__ bool build_action(const ObservationView&raw,const DeviceBasePack&bp,const bonsaikg4_champion::CudaLegacyPack&lp,bonsaikg4_champion::CudaLegacyState&legacy,bonsaikg_v6::CudaEngineExploitState&exploit,const int32_t*bb,int feed_slot,int feed_count,int strategic_slot,uint16_t route_override,Action&out){int route=bb[1];if(strategic_slot>=0&&bb[strategic_slot])route=bb[strategic_slot];if(route_override!=bonsaikg4::NONE_U16)route=route_override;const auto*p=bp.at((uint16_t)route,raw.step());if(!p)return false;bonsaikg_v6::materialize_cuda(*p,raw.farm(raw.player()).n_units(),out);bonsaikg4_champion::apply_legacy(raw,lp,legacy,out);bonsaikg_v6::apply_cuda_engine_exploits(raw,out,exploit,legacy.external_ok!=0,100);reconcile_feed(bb,feed_slot,feed_count,out);return true;}

__global__ void eval_kernel(Config cfg0,DeviceTables tables,bonsaikg4::PolicyView4 policy,DeviceBasePack bp,bonsaikg4_champion::CudaLegacyPack lp,const Action*opp,const OppDesc*od,const CaseDev*cases,int nc,const inv::Candidate*cands,int ng,int feed_slot,int feed_count,int strategic_slot,int32_t*bb,bonsaikg4::NodeState4*ns,bonsaikg4::RuntimeMeta4*meta,Sim*sims,ResultBin*out){
    int job=blockIdx.x*blockDim.x+threadIdx.x,total=nc*ng;if(job>=total)return;int gi=job/nc,ci=job-gi*nc;const CaseDev c=cases[ci];Config cfg=cfg0;cfg.seed=c.seed;Sim&sim=sims[job];sim.init(cfg,&tables);bonsaikg4::RuntimeView4 st{policy.n_bb?bb+(size_t)job*policy.n_bb:nullptr,policy.n_state?ns+(size_t)job*policy.n_state:nullptr,meta+job};bonsaikg4::reset_runtime(policy,st);bonsaikg4_champion::CudaLegacyState legacy{};bonsaikg_v6::CudaEngineExploitState exploit{};bonsaikg4_champion::reset_legacy(legacy);bonsaikg_v6::reset_cuda_engine_exploits(exploit);inv::RuntimeState ims{};uint16_t changes=0,acts=0,flags=0;uint64_t th=1469598103934665603ull;const auto&cand=cands[gi];
    while(!sim.st.done){int os=1-c.seat;ObservationView raw=make_observation(sim,c.seat);bonsaikg4::CudaObservation4 obs4(raw);bonsaikg4::ActionResult4 ignored{};auto status=bonsaikg4::tick4(policy,st,obs4,0,ignored,nullptr);if(meta[job].fault||status!=bonsaikg4::SUCCESS){flags|=1;break;}auto d=inv::evaluate(cand,ims,obs4);if(acts!=0xffffu){unsigned v=(unsigned)acts+(unsigned)d.activations;acts=(uint16_t)(v>65535?65535:v);}Action baseline{},candidate{};
        if(d.route_override==bonsaikg4::NONE_U16){if(!build_action(raw,bp,lp,legacy,exploit,st.blackboard,feed_slot,feed_count,strategic_slot,bonsaikg4::NONE_U16,candidate)){flags|=2;break;}baseline=candidate;}else{auto lcmp=legacy;auto ecmp=exploit;if(!build_action(raw,bp,lp,lcmp,ecmp,st.blackboard,feed_slot,feed_count,strategic_slot,bonsaikg4::NONE_U16,baseline)){flags|=2;break;}if(!build_action(raw,bp,lp,legacy,exploit,st.blackboard,feed_slot,feed_count,strategic_slot,d.route_override,candidate)){flags|=2;break;}}
        inv::apply_post(cand,d,candidate,10);if(!same_action(candidate,baseline)&&changes!=0xffffu)++changes;th=trace_hash(th,sim.st.step,candidate);Action oa{};OppDesc dd=od[c.tape];if(dd.count){int s=sim.st.step<dd.count?sim.st.step:dd.count-1;oa=opp[dd.first+s];}oa.n_units=sim.st.farms[os].n_units;if(c.seat==0)sim.step_with_unit_counts(candidate,sim.st.farms[0].n_units,oa,sim.st.farms[1].n_units);else sim.step_with_unit_counts(oa,sim.st.farms[0].n_units,candidate,sim.st.farms[1].n_units);
    }
    ResultBin r{};r.own_money=(int32_t)sim.st.farms[c.seat].money;r.opp_money=(int32_t)sim.st.farms[1-c.seat].money;r.action_changes=changes;r.activations=acts;r.flags=flags;r.action_trace_hash=th;out[job]=r;
}

static void write_results(const std::string&p,const std::vector<ResultBin>&rows,int ng,int nc){std::ofstream o(p,std::ios::binary);if(!o)throw std::runtime_error("cannot write B4IC1 results");ResultHeader h{{'B','4','I','C','1','\0','\0','\0'},1u,(uint32_t)ng,(uint32_t)nc};o.write((char*)&h,sizeof(h));o.write((char*)rows.data(),rows.size()*sizeof(rows[0]));}
}

int main(int argc,char**argv){try{
    std::string controller,routes,legacy,casesp,candsp,outp;int feed_slot=5,feed_count=13,strategic_slot=19,tpb=64,device=-1;double memfrac=.70;
    for(int i=1;i<argc;++i){std::string a=argv[i];auto need=[&](){if(i+1>=argc)throw std::runtime_error("missing value for "+a);return std::string(argv[++i]);};if(a=="--controller")controller=need();else if(a=="--routes")routes=need();else if(a=="--legacy-routes")legacy=need();else if(a=="--cases")casesp=need();else if(a=="--candidates")candsp=need();else if(a=="--out")outp=need();else if(a=="--feed-slot")feed_slot=std::stoi(need());else if(a=="--feed-count")feed_count=std::stoi(need());else if(a=="--strategic-route-slot")strategic_slot=std::stoi(need());else if(a=="--tpb")tpb=std::stoi(need());else if(a=="--device")device=std::stoi(need());else if(a=="--memory-fraction")memfrac=std::stod(need());else throw std::runtime_error("unknown argument "+a);}if(controller.empty()||routes.empty()||legacy.empty()||casesp.empty()||candsp.empty()||outp.empty())throw std::runtime_error("required: --controller --routes --legacy-routes --cases --candidates --out");if(device>=0)KAGCUDA_CHECK(cudaSetDevice(device));
    auto owned=bonsaikg4::load_compiled4(controller);auto hp=owned.view();if(hp.n_bb<(uint16_t)(feed_slot+feed_count))throw std::runtime_error("feed slots outside policy BB");if(strategic_slot>=0&&hp.n_bb<=(uint16_t)strategic_slot)throw std::runtime_error("strategic route slot outside policy BB");DevicePolicyOwner4 po;po.n=cp(owned.nodes);po.c=cp(owned.child_refs);po.bb=cp(owned.bb);po.v=cp(owned.values);po.a=cp(owned.feature_args);po.q=cp(owned.predicates);po.l=cp(owned.lifecycles);po.e=cp(owned.effects);auto dp=hp;dp.nodes=po.n;dp.child_refs=po.c;dp.bb=po.bb;dp.values=po.v;dp.feature_args=po.a;dp.predicates=po.q;dp.lifecycles=po.l;dp.effects=po.e;
    auto rp=bonsaikg4_champion::load_extended_route_pack(routes),lph=load_legacy_pack(legacy);auto*dr=cp(rp.routes);auto*da=cp(rp.actions);auto*dlr=cp(lph.routes);auto*dla=cp(lph.actions);DeviceBasePack bp{dr,da,(int)rp.routes.size()};bonsaikg4_champion::CudaLegacyPack lpd{dlr,dla,(int)lph.routes.size()};auto hc=load_cases(casesp);auto hg=load_candidates(candsp);std::vector<Action>hoa;std::vector<OppDesc>hod;std::vector<CaseDev>hcd;std::unordered_map<std::string,int>cache;for(const auto&c:hc){int ti=-1;auto it=cache.find(c.path);if(it!=cache.end())ti=it->second;else{auto t=load_native_tape(c.path);int off=(int)hoa.size();hoa.insert(hoa.end(),t.actions.begin(),t.actions.end());ti=(int)hod.size();hod.push_back({off,(int)t.actions.size()});cache.emplace(c.path,ti);}hcd.push_back({ti,c.seat,c.seed,c.family,c.protected_flag,c.own_history,c.role});}
    auto*doa=cp(hoa);auto*dod=cp(hod);auto*dc=cp(hcd);auto*dg=cp(hg);configure_device();TablesOwner tables;size_t freeb=0,totalb=0;KAGCUDA_CHECK(cudaMemGetInfo(&freeb,&totalb));size_t perjob=(size_t)hp.n_bb*sizeof(int32_t)+(size_t)hp.n_state*sizeof(bonsaikg4::NodeState4)+sizeof(bonsaikg4::RuntimeMeta4)+sizeof(Sim)+sizeof(ResultBin);size_t maxjobs=(size_t)(freeb*memfrac)/perjob;size_t nc=hc.size();if(maxjobs<nc)throw std::runtime_error("case pool exceeds GPU memory budget");size_t chunkg=maxjobs/nc;if(chunkg<1)chunkg=1;if(chunkg>hg.size())chunkg=hg.size();size_t capjobs=nc*chunkg,jobs=nc*hg.size();int32_t*dbb=nullptr;bonsaikg4::NodeState4*dns=nullptr;bonsaikg4::RuntimeMeta4*dm=nullptr;Sim*ds=nullptr;ResultBin*dout=nullptr;if(hp.n_bb)KAGCUDA_CHECK(cudaMalloc((void**)&dbb,capjobs*hp.n_bb*sizeof(int32_t)));if(hp.n_state)KAGCUDA_CHECK(cudaMalloc((void**)&dns,capjobs*hp.n_state*sizeof(bonsaikg4::NodeState4)));KAGCUDA_CHECK(cudaMalloc((void**)&dm,capjobs*sizeof(*dm)));KAGCUDA_CHECK(cudaMalloc((void**)&ds,capjobs*sizeof(*ds)));KAGCUDA_CHECK(cudaMalloc((void**)&dout,capjobs*sizeof(*dout)));
    Config cfg;cfg.episode_steps=720;cudaEvent_t e0,e1;KAGCUDA_CHECK(cudaEventCreate(&e0));KAGCUDA_CHECK(cudaEventCreate(&e1));std::vector<ResultBin>hr(jobs);double ms=0;size_t chunks=0;for(size_t start=0;start<hg.size();start+=chunkg){size_t ng=std::min(chunkg,hg.size()-start),cj=nc*ng;KAGCUDA_CHECK(cudaEventRecord(e0));eval_kernel<<<(cj+tpb-1)/tpb,tpb>>>(cfg,tables.dev,dp,bp,lpd,doa,dod,dc,(int)nc,dg+start,(int)ng,feed_slot,feed_count,strategic_slot,dbb,dns,dm,ds,dout);KAGCUDA_CHECK(cudaGetLastError());KAGCUDA_CHECK(cudaEventRecord(e1));KAGCUDA_CHECK(cudaEventSynchronize(e1));float cms=0;KAGCUDA_CHECK(cudaEventElapsedTime(&cms,e0,e1));ms+=cms;KAGCUDA_CHECK(cudaMemcpy(hr.data()+start*nc,dout,cj*sizeof(ResultBin),cudaMemcpyDeviceToHost));++chunks;}write_results(outp,hr,(int)hg.size(),(int)hc.size());unsigned long long changes=0,acts=0;int bad=0;for(auto&r:hr){bad+=r.flags!=0;changes+=r.action_changes;acts+=r.activations;}std::cout<<"B4IC1 candidates="<<hg.size()<<" cases="<<hc.size()<<" games="<<jobs<<" gpu_ms="<<ms<<" games_s="<<(jobs/(ms/1000.0))<<" chunks="<<chunks<<" chunk_candidates="<<chunkg<<" candidate_bytes="<<sizeof(inv::Candidate)<<" per_job_bytes="<<perjob<<" action_changes="<<changes<<" activations="<<acts<<" bad="<<bad<<"\n";
    cudaFree(dr);cudaFree(da);cudaFree(dlr);cudaFree(dla);cudaFree(doa);cudaFree(dod);cudaFree(dc);cudaFree(dg);if(dbb)cudaFree(dbb);if(dns)cudaFree(dns);cudaFree(dm);cudaFree(ds);cudaFree(dout);cudaEventDestroy(e0);cudaEventDestroy(e1);return bad?1:0;
}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
